static int cmp_first_then_second(const void *a, const void *b) {
    const int *x = (const int *)a;
    const int *y = (const int *)b;
    if (x[0] != y[0]) return x[0] < y[0] ? -1 : 1;
    if (x[1] != y[1]) return x[1] < y[1] ? -1 : 1;
    return 0;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int E = N - 1 + M;

    /* store all directed edges (u -> v), where u is ancestor of v */
    int (*pairs)[2] = (int (*)[2])malloc(sizeof(int[2]) * E);
    int *indeg = (int *)calloc(N + 1, sizeof(int));

    for (int i = 0; i < E; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        pairs[i][0] = u;
        pairs[i][1] = v;
        indeg[v]++;
    }

    /* root is the unique vertex with indegree 0 */
    int root = 1;
    for (int i = 1; i <= N; i++) {
        if (indeg[i] == 0) {
            root = i;
            break;
        }
    }

    /*
      Key fact:
      For each non-root vertex v, its parent is exactly the ancestor u of v
      with maximum depth among all given edges u -> v.
      Since every tree edge parent(v) -> v is included, and any other ancestor
      is shallower, parent(v) is the "closest" predecessor of v.

      We reconstruct depths in topological order:
      depth[root] = 0
      depth[v] = max(depth[u] + 1) over all given edges u -> v
      and parent[v] is the u achieving that maximum.
    */

    /* sort by destination to process incoming edges of each vertex */
    qsort(pairs, E, sizeof(int[2]), cmp_first_then_second);

    int *parent = (int *)calloc(N + 1, sizeof(int));
    int *depth = (int *)calloc(N + 1, sizeof(int));

    parent[root] = 0;
    depth[root] = 0;

    int idx = 0;
    while (idx < E) {
        int u = pairs[idx][0];
        int v = pairs[idx][1];
        (void)u;

        int curv = v;
        int bestParent = 0;
        int bestDepth = -1;

        while (idx < E && pairs[idx][1] == curv) {
            int from = pairs[idx][0];
            if (depth[from] > bestDepth) {
                bestDepth = depth[from];
                bestParent = from;
            }
            idx++;
        }

        parent[curv] = bestParent;
        depth[curv] = bestDepth + 1;
    }

    for (int i = 1; i <= N; i++) {
        printf("%d\n", parent[i]);
    }

    free(pairs);
    free(indeg);
    free(parent);
    free(depth);
    return 0;
}

