int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;
    int E = N - 1 + M;

    vector<vector<int>> g(N + 1);
    vector<int> indeg(N + 1, 0);

    for (int i = 0; i < E; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        indeg[v]++;
    }

    // In the transitive closure-like DAG formed by tree edges + added ancestor->descendant edges:
    // - The root is the unique vertex with indegree 0.
    // - For any non-root vertex v, its parent is the unique predecessor u of v
    //   such that indeg[u] = indeg[v] - 1.
    //
    // Reason:
    // indeg[x] equals the number of ancestors of x.
    // If p is the parent of v, then ancestors(v) = ancestors(p) + {p},
    // so indeg[v] = indeg[p] + 1.
    // Any other predecessor is a higher ancestor and has smaller indegree.

    int root = -1;
    for (int v = 1; v <= N; v++) {
        if (indeg[v] == 0) {
            root = v;
            break;
        }
    }

    vector<int> parent(N + 1, -1);
    parent[root] = 0;

    for (int u = 1; u <= N; u++) {
        for (int v : g[u]) {
            if (indeg[u] + 1 == indeg[v]) {
                parent[v] = u;
            }
        }
    }

    for (int v = 1; v <= N; v++) {
        cout << parent[v] << '\n';
    }

    return 0;
}

