        List<Integer>[] outgoing = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) {
            incoming[i] = new ArrayList<>();
            outgoing[i] = new ArrayList<>();
        }

        int[] indeg = new int[N + 1];
        for (int i = 0; i < N - 1 + M; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            outgoing[u].add(v);
            incoming[v].add(u);
            indeg[v]++;
        }

        // Find root: indegree 0
        int root = -1;
        for (int i = 1; i <= N; i++) {
            if (indeg[i] == 0) {
                root = i;
                break;
            }
        }

        int[] parent = new int[N + 1];
        int[] depth = new int[N + 1];
        Arrays.fill(depth, -1);
        depth[root] = 0;

        Queue<Integer> queue = new LinkedList<>();
        queue.add(root);

        while (!queue.isEmpty()) {
            int u = queue.poll();
            for (int v : outgoing[u]) {
                if (depth[v] == -1) {
                    depth[v] = depth[u] + 1;
                    // Among all incoming edges, pick the one with max depth
                    int bestParent = -1;
                    int bestDepth = -1;
                    for (int p : incoming[v]) {
                        if (depth[p] != -1 && depth[p] > bestDepth) {
                            bestDepth = depth[p];
                            bestParent = p;
                        }
                    }
                    parent[v] = bestParent;
                    queue.add(v);
                }
            }
        }

        // Output
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= N; i++) {
            sb.append(parent[i]).append("\n");
        }
        System.out.print(sb);
    }
}

