public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();

        // indeg[v] > 0 means v has at least one incoming edge in the given graph
        int[] indeg = new int[N + 1];

        // For each u, store all descendants v such that edge u -> v is given
        ArrayList<Integer>[] g = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < N - 1 + M; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            g[u].add(v);
            indeg[v]++;
        }

        // Root is the only vertex with no incoming edge
        int root = 1;
        for (int i = 1; i <= N; i++) {
            if (indeg[i] == 0) {
                root = i;
                break;
            }
        }

        int[] parent = new int[N + 1];
        parent[root] = 0;

        // Process vertices in topological/tree order.
        // When processing u, among all outgoing edges u -> x,
        // the direct children of u are exactly those vertices x
        // that do not already have a parent assigned.
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(root);

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g[u]) {
                if (parent[v] == 0 && v != root) {
                    parent[v] = u;
                    q.add(v);
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= N; i++) {
            sb.append(parent[i]).append('\n');
        }
        System.out.print(sb.toString());
    }
}

